const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const cfg=JSON.parse(process.env.PINPOINT_BROWSER_CONFIG),root=cfg.sourceRoot;
const {chromium}=require(path.join(root,'node_modules/playwright'));
const TARGET_URL=cfg.origin,checks=[],errors=[],contexts=[];let browser,passed=false;
const sast=value=>new Date(value+7200000).toISOString().slice(0,19);
async function context(cookies,width=1218){const c=await browser.newContext({viewport:{width,height:width<500?844:900},timezoneId:'America/Los_Angeles',reducedMotion:'reduce'});contexts.push(c);await c.route('**/*',async route=>{const u=new URL(route.request().url());if([TARGET_URL,'http://127.0.0.1:55431'].includes(u.origin))await route.continue();else if(u.hostname==='api.maptiler.com')await route.fulfill({contentType:'application/json',body:JSON.stringify({version:8,sources:{},layers:[{id:'fixture-background',type:'background',paint:{'background-color':'#e6eadf'}}]})});else if(u.hostname==='www.google.com')await route.fulfill({contentType:'text/html',body:'<p>Captured fixed-host directions; no external navigation.</p>'});else await route.abort();});
 await c.route(/\/api\/(private\/offers\/places|offers\/places|places)\?q=/,async route=>{const response=await route.fetch({url:TARGET_URL+'/api/places/'+cfg.place});const result=await response.json();await route.fulfill({contentType:'application/json',body:JSON.stringify({data:{places:[result.data.place]}})});});
 if(cookies)await c.addCookies(cookies);c.on('page',page=>{page.setDefaultTimeout(120000);page.on('pageerror',e=>errors.push(e.message));});return c;}
async function navigate(page,url){await page.goto(url,{waitUntil:'domcontentloaded',timeout:120000});}
async function click(page,name){const button=page.getByRole('button',{name,exact:true});await button.waitFor();await button.click();}
async function save(page){await click(page,'Save private draft');await page.getByText('Private draft saved.',{exact:true}).waitFor();}
async function complete(page,title,start,end){await page.getByLabel('Entry title',{exact:true}).fill(title);await page.getByLabel('Description',{exact:true}).fill('Synthetic native browser fixture. Not real supply.');await page.getByLabel('Venue name',{exact:true}).fill('Synthetic browser venue');await page.getByLabel('Street address',{exact:true}).fill('Synthetic exact venue address');await page.getByLabel('Venue latitude',{exact:true}).fill('-33.97');await page.getByLabel('Venue longitude',{exact:true}).fill('18.48');await page.getByLabel('Starts at (SAST)',{exact:true}).fill(sast(start));await page.getByLabel('Ends at (SAST)',{exact:true}).fill(sast(end));await page.getByRole('button',{name:/^Location:/}).click();await page.getByRole('combobox',{name:'Search South African locations'}).fill('Entry fixture');await page.getByRole('option',{name:/Entry fixture area/}).first().click();await save(page);await page.reload({waitUntil:'domcontentloaded'});assert.equal(await page.getByLabel('Entry title',{exact:true}).inputValue(),title);await click(page,'Submit for review');await page.getByText('Submitted for admin review. This entry is not public.',{exact:true}).waitFor();await page.getByRole('checkbox').check();await click(page,'Confirm publishing permission');await page.getByText('Permission confirmed for this submitted revision. An administrator must still check and approve it.',{exact:true}).waitFor();}
async function review(page,title,decision='approve'){await navigate(page,TARGET_URL+'/admin/entries');const section=page.locator('section').filter({has:page.getByRole('heading',{name:title,exact:true})});await section.waitFor();if(decision==='approve'){await section.getByLabel('Authority evidence',{exact:true}).fill('Synthetic venue permission reviewed. Fixture only.');await section.getByLabel('Venue, location and date evidence',{exact:true}).fill('Synthetic stored location, exact point and SAST dates checked.');await section.getByRole('checkbox').check();const result=page.waitForResponse(r=>r.url().endsWith('/api/private/entries/review')&&r.request().method()==='POST');await section.getByRole('button',{name:'Approve special',exact:true}).click();assert.equal((await result).status(),200);await section.getByText('Approved revision',{exact:true}).waitFor();}else{await section.getByLabel('Correction or removal reason',{exact:true}).fill('Synthetic correction required');const result=page.waitForResponse(r=>r.url().endsWith('/api/private/entries/review')&&r.request().method()==='POST');await section.getByRole('button',{name:'Request correction',exact:true}).click();assert.equal((await result).status(),200);await section.waitFor({state:'detached'});}}
async function publicPage(page,category,view='feed'){await navigate(page,TARGET_URL+'/offers?'+new URLSearchParams({kind:category,areaId:cfg.place,view}));await page.getByRole('button',{name:'Refresh specials',exact:true}).waitFor();}
async function geometry(page){assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1),false,'Horizontal overflow');assert.equal(await page.locator('[data-slot="pinpoint-header"]').count(),1);}
(async()=>{try{
 browser=await chromium.launch({headless:false,args:['--enable-unsafe-swiftshader']});
 const poster=await context(cfg.posterCookies),p=await poster.newPage(),reviewer=await context(cfg.adminCookies),a=await reviewer.newPage(),visitor=await context(),v=await visitor.newPage();
 await navigate(p,TARGET_URL+'/post/entries/tourism');await click(p,'New Tourism entry');await p.waitForURL(/\/post\/entries\/tourism\/[a-f0-9-]+/);const tourismUrl=p.url(),tourismId=new URL(tourismUrl).pathname.split('/').at(-1);
 await p.getByLabel('Entry title',{exact:true}).fill('Browser Tourism partial');await save(p);await p.reload({waitUntil:'domcontentloaded'});assert.equal(await p.getByLabel('Entry title',{exact:true}).inputValue(),'Browser Tourism partial');await click(p,'Submit for review');await p.getByRole('alert').filter({hasText:/Check description/i}).waitFor();
 const stale=await poster.newPage();await navigate(stale,tourismUrl);await stale.getByLabel('Entry title',{exact:true}).fill('Unsaved conflict text');await p.getByLabel('Entry title',{exact:true}).fill('Fresh browser title');await save(p);const staleResponse=stale.waitForResponse(r=>r.url().includes('/api/private/entries')&&r.status()===409);await click(stale,'Save private draft');await staleResponse;await stale.getByRole('alert').filter({hasText:/unsaved text/i}).waitFor();assert.equal(await stale.getByLabel('Entry title',{exact:true}).inputValue(),'Unsaved conflict text');await stale.close();
 checks.push('Native cookie private create/partial save/reload; incomplete submission denied; real stale HTTP 409 retains unsaved text');console.log('PASS browser private/stale');
 const tourismTitle='Browser Tourism fixture';await complete(p,tourismTitle,Date.now()-86400000,Date.now()+86400000);await review(a,tourismTitle);
 await publicPage(v,'tourism','map');await v.getByRole('heading',{name:tourismTitle,exact:true}).waitFor();await v.getByRole('button',{name:'Show '+tourismTitle,exact:true}).waitFor();await geometry(v);await v.screenshot({path:path.join(root,'docs/pinpoint-phase2-tourism-desktop.png')});await v.getByRole('button',{name:'Show '+tourismTitle,exact:true}).click();
 await v.getByRole('button',{name:'Feed',exact:true}).click();await v.waitForURL(/view=feed/);await v.getByRole('heading',{name:tourismTitle,exact:true}).waitFor();assert.equal(await v.locator('[data-slot="category-map"]').count(),0);
 await v.getByRole('link',{name:tourismTitle,exact:true}).click();await v.getByRole('button',{name:'Get venue directions',exact:true}).waitFor();await v.getByRole('button',{name:'Get venue directions',exact:true}).click();await v.waitForURL(u=>u.hostname==='www.google.com');const destination=new URL(v.url());assert.equal(destination.pathname,'/maps/dir/');assert.equal(destination.searchParams.get('destination'),'-33.97,18.48');
 checks.push('Native poster permission and real MFA reviewer approval; anonymous Tourism approved card/pin, map-free Feed, detail/SAST and fresh fixed-host directions');console.log('PASS browser Tourism public');
 const foreign=await context(cfg.foreignCookies),f=await foreign.newPage();await navigate(f,TARGET_URL+'/post/entries/event');await click(f,'Enroll in Events');await f.getByText('Enrolled for this category.',{exact:true}).waitFor();await f.reload({waitUntil:'domcontentloaded'});await f.getByRole('button',{name:'New Event',exact:true}).waitFor();checks.push('Native separate Event enrollment persists across reload without granting Tourism or foreign-entry access');await navigate(f,tourismUrl);assert.equal(await f.getByLabel('Entry title',{exact:true}).count(),0);const forged=await f.evaluate(async target=>{const r=await fetch('/api/private/entries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command:'save',category:'tourism',entryId:target,expectedVersion:1,draft:{title:'Stolen'}})});return r.status;},tourismId);assert.equal(forged,403);await f.close();
 await navigate(p,tourismUrl);await p.getByLabel('Entry title',{exact:true}).fill('Browser Tourism replacement');await save(p);await click(p,'Submit for review');await p.getByText('Submitted for admin review. This entry is not public.',{exact:true}).waitFor();await review(a,'Browser Tourism replacement','reject');await publicPage(v,'tourism');assert.equal(await v.getByRole('heading',{name:tourismTitle,exact:true}).count(),0);await navigate(v,TARGET_URL+'/specials/'+tourismId);await v.getByRole('heading',{name:'This special is unavailable',exact:true}).waitFor();assert.equal(await v.getByRole('button',{name:'Get venue directions',exact:true}).count(),0);await navigate(p,tourismUrl);await p.getByText('Last reviewer feedback: Synthetic correction required',{exact:true}).waitFor();
 checks.push('Native foreign-owner read/write refusal; material resubmission hides publication; correction feedback persists and rejecting replacement never revives old detail');console.log('PASS browser correction/privacy');
 // Renewal with a new revision and withdrawal on an open anonymous detail.
 await click(p,'Submit for review');await p.getByText('Submitted for admin review. This entry is not public.',{exact:true}).waitFor();await p.getByRole('checkbox').check();await click(p,'Confirm publishing permission');await p.getByText('Permission confirmed for this submitted revision. An administrator must still check and approve it.',{exact:true}).waitFor();await review(a,'Browser Tourism replacement');await navigate(v,TARGET_URL+'/specials/'+tourismId);await v.getByRole('heading',{name:'Browser Tourism replacement',exact:true}).waitFor();
 await navigate(p,tourismUrl);await click(p,'Withdraw entry');await click(p,'Confirm withdrawal');await p.getByText('Entry withdrawn. The pending review was cancelled.',{exact:true}).waitFor();await v.getByRole('heading',{name:'This special is unavailable',exact:true}).waitFor({timeout:35000});assert.equal(await v.getByRole('button',{name:'Get venue directions',exact:true}).count(),0);
 checks.push('Native fresh renewal/approval and withdrawal remove content from already open visitor detail without scheduled jobs');console.log('PASS browser withdrawal');
 // Phone Event enters SAST including seconds, while browser timezone is Los Angeles.
 await p.setViewportSize({width:390,height:844});await a.setViewportSize({width:390,height:844});await v.setViewportSize({width:390,height:844});await navigate(p,TARGET_URL+'/post/entries/event');await click(p,'New Event');await p.waitForURL(/\/post\/entries\/event\/[a-f0-9-]+/);const eventUrl=p.url(),eventId=new URL(eventUrl).pathname.split('/').at(-1),start=Date.now()+90000,end=start+30000,title='Browser Upcoming Event';await complete(p,title,start,end);await review(a,title);await publicPage(v,'event','map');await v.getByRole('heading',{name:title,exact:true}).waitFor();await v.getByText('Upcoming',{exact:true}).waitFor();await v.getByRole('button',{name:'Show '+title,exact:true}).waitFor();await geometry(v);await v.screenshot({path:path.join(root,'docs/pinpoint-phase2-event-phone.png')});await navigate(v,TARGET_URL+'/specials/'+eventId);await v.getByRole('status').filter({hasText:'Upcoming'}).waitFor();await v.getByRole('button',{name:'Get venue directions',exact:true}).waitFor();
 checks.push('390px native Event save/submit/permission/MFA review/reload; approved future Event card/pin/detail are Upcoming with SAST dates and venue directions');console.log('PASS browser Event upcoming; waiting for exact live/end boundaries');
 await v.getByRole('status').filter({hasText:'Available now'}).waitFor({timeout:150000});await v.getByRole('heading',{name:'This special is unavailable',exact:true}).waitFor({timeout:60000});assert.equal(await v.getByRole('button',{name:'Get venue directions',exact:true}).count(),0);const ended=await v.request.get(TARGET_URL+'/api/entries/'+eventId+'/directions');assert.equal(ended.status(),404);
 await publicPage(v,'event');await v.getByText('No current events specials in this area.',{exact:true}).waitFor();assert.equal(await v.getByRole('heading',{name:title,exact:true}).count(),0);await geometry(v);
 checks.push('Already open future Event transitions Upcoming → live at exact start → unavailable at exact end; directions 404 and feed removal, no cron dependency');console.log('PASS browser exact Event boundaries');
 // API failure is visibly unavailable; retry after recovery is empty, not leaked data.
 await visitor.route('**/api/entries?**',route=>route.fulfill({status:503,contentType:'application/json',body:'{"error":"Fixture failure"}'}));await v.getByRole('button',{name:'Refresh specials',exact:true}).click();await v.getByRole('alert').filter({hasText:'Could not load specials'}).waitFor();await visitor.unroute('**/api/entries?**');await v.getByRole('button',{name:'Refresh specials',exact:true}).click();await v.getByText('No current events specials in this area.',{exact:true}).waitFor();
 checks.push('Phone failed public response removes content; explicit refresh recovers to truthful empty state');
 assert.deepEqual(errors,[]);passed=true;
 }catch(e){console.error({name:e.name,message:e.message});errors.push(e.message);process.exitCode=1;}finally{if(browser)await browser.close();fs.writeFileSync(cfg.resultPath,JSON.stringify({passed,checks,errors,substitutions:'Blank MapTiler basemap, place-search suggestion backed by stored clone UUID and intercepted final Google Maps navigation; Auth/MFA/cookies/private/public APIs/DB are real',viewports:[{width:1218,height:900},{width:390,height:844}],timezone:'America/Los_Angeles'},null,2));}
})().catch(e=>{console.error(e.message);process.exitCode=1});
